import java.util.Scanner;

public class Main {
    static final int MAXN = 1000111;
    static final long MOD = 1000000007;

    static long[] visited = new long[MAXN];
    static long[] countMap = new long[MAXN];

    static long modExponentiation(long base, int exponent) {
        long res = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(modExponentiation(p, p - 1));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(modExponentiation(p, p));
            sc.close();
            return;
        }

        for (int i = 0; i < p; i++) {
            visited[i] = 0;
            countMap[i] = 0;
        }

        for (int start = 1; start < p; start++) {
            if (visited[start] != 0) continue;
            long current = start;
            int length = 0;
            while (visited[(int) current] == 0) {
                visited[(int) current] = 1;
                current = (current * k) % p;
                length++;
            }
            countMap[length]++;
        }

        long answer = 1;
        for (int len = 1; len <= p - 1; len++) {
            if (countMap[len] == 0) continue;
            long tmp = modExponentiation((len * countMap[len] + 1) % MOD, (int) countMap[len]);
            answer = (answer * tmp) % MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}
